async def act(page):
    # 1) Scroll to the bottom of the page in steps so lazy content/pagination can load
    await page.evaluate("""async () => {
        await new Promise(resolve => {
            const step = 800;
            const interval = 100;
            const id = setInterval(() => {
                window.scrollBy(0, step);
                if ((window.innerHeight + window.scrollY) >= document.body.scrollHeight) {
                    clearInterval(id);
                    setTimeout(resolve, 250);
                }
            }, interval);
        });
    }""")

    # 2) Try direct accessible name 'Page 5'
    page5_named = page.get_by_role("link", name="Page 5")
    if await page5_named.count() > 0:
        await page5_named.first.click()
        return

    # 3) Try accessible name '5' but verify href patterns to avoid clicking unrelated '5' links
    page5_simple = page.get_by_role("link", name="5")
    if await page5_simple.count() > 0:
        c = await page5_simple.count()
        for i in range(c):
            link = page5_simple.nth(i)
            try:
                href = await link.get_attribute("href") or ""
                text = (await link.inner_text()).strip()
            except Exception:
                href = ""
                text = ""
            if href and ("paged=5" in href or "/page/5" in href or "?page=5" in href or "page/5" in href or "page=5" in href):
                await link.click()
                return
            # fallback: if the visible text is exactly '5' and it has an href, prefer it
            if text == "5" and href:
                await link.click()
                return

    # 4) Last-resort: scan all links for pagination-like hrefs or for visible text that includes 'page 5'
    all_links = page.get_by_role("link")
    total = await all_links.count()
    for i in range(total):
        l = all_links.nth(i)
        try:
            href = await l.get_attribute("href") or ""
            text = (await l.inner_text()).strip()
        except Exception:
            continue
        if href and ("paged=5" in href or "/page/5" in href or "?page=5" in href or "page/5" in href or "page=5" in href):
            await l.click()
            return
        if "page 5" in text.lower():
            await l.click()
            return

    # If we reach here, no page-5 link was found
    print('Could not find a link to page 5 on the current page after scrolling.')

